WITH Base AS (SELECT * FROM employees WHERE YEAR(hire_date) >= 2025 AND dept_id = 5), summary AS (SELECT is_remote, CASE WHEN salary >= 164000 THEN 'high' WHEN salary >= 73000 THEN 'mid' ELSE 'low' END AS salary_bucket, ROUND(AVG(salary), 2) AS avg_salary FROM Base GROUP BY is_remote, CASE WHEN salary >= 164000 THEN 'high' WHEN salary >= 73000 THEN 'mid' ELSE 'low' END) SELECT is_remote, salary_bucket FROM summary ORDER BY salary_bucket
